const doc = $input.first().json;
const slots = $('Make CV input').first().json.slots;
const documentId = $('Copy CV template').first().json.id;
const DEL = '§§DEL§§';


const content = (doc.body && doc.body.content) || [];
const endOfBody = content.length ? content[content.length - 1].endIndex : 0;

// Header (name and contact line) from the master profile, if one is known
const profile = $('Make CV input').first().json.profile || {};
const headerRepl = [];
const paraText = block => (block.paragraph.elements || []).map(el => (el.textRun ? el.textRun.content : '')).join('').replace(/\n$/, '').trim();
if (profile.name || profile.email || profile.phone || profile.linkedin) {
  const words = String(profile.name || '').trim().split(/\s+/).filter(Boolean);
  const last = words.length > 1 ? words.pop() : '';
  const first = words.join(' ');
  const cap = w => (w ? w.charAt(0).toUpperCase() + w.slice(1).toLowerCase() : w);
  const plainName = (first + ' ' + last.split('-').map(cap).join('-')).trim();
  const headerName = last ? first + ' ' + last.toUpperCase() : first.toUpperCase();
  const contact = [profile.email, profile.phone, profile.linkedin].filter(Boolean).join('  |  ');
  const doneTexts = new Set();
  for (const block of content) {
    if (!block.paragraph) continue;
    const t = paraText(block);
    if (!t || doneTexts.has(t)) continue;
    if (profile.name && /^alex\s+martin$/i.test(t)) { headerRepl.push([t, /MARTIN/.test(t) ? headerName : plainName]); doneTexts.add(t); }
    else if (contact && /@example\.com/i.test(t)) { headerRepl.push([t, contact]); doneTexts.add(t); }
  }
}

// 1) Paragraphs to delete: any paragraph holding a placeholder whose value is the marker
const toDelete = [];
const seen = new Set();
for (const block of content) {
  if (!block.paragraph) continue;
  const text = (block.paragraph.elements || []).map(el => (el.textRun ? el.textRun.content : '')).join('');
  const keys = [...text.matchAll(/\{\{(\w+)\}\}/g)].map(m => m[1]);
  keys.forEach(k => seen.add(k));
  if (keys.some(k => slots[k] === DEL || !(k in slots))) {   // unused or unknown placeholder: remove the paragraph
    // the last newline of the document can never be deleted
    toDelete.push({ start: block.startIndex, end: Math.min(block.endIndex, endOfBody - 1) });
  }
}
toDelete.sort((a, b) => b.start - a.start);   // from the end, so earlier indexes stay valid

// 2) Requests: delete the unused paragraphs first, then replace every other placeholder
const requests = toDelete.map(r => ({ deleteContentRange: { range: { startIndex: r.start, endIndex: r.end } } }));
for (const [key, value] of Object.entries(slots)) {
  if (value === DEL) continue;
  requests.push({ replaceAllText: { containsText: { text: '{{' + key + '}}', matchCase: true }, replaceText: String(value) } });
}

for (const [from, to] of headerRepl) requests.push({ replaceAllText: { containsText: { text: from, matchCase: true }, replaceText: to } });

// 3) Safety: placeholders in the document that have no value
const missing = [...seen].filter(k => !(k in slots));

return [{ json: {
  documentId,
  deleted: toDelete.length,
  replacements: requests.length - toDelete.length,
  missing,
  body: { requests }
} }];

const it = $input.first();
const bin = it.binary || {};
const key = Object.keys(bin)[0];
if (!key) return [{ json: { ok: false, error: 'CV file missing' } }];
const buf = await this.helpers.getBinaryDataBuffer(0, key);
const company = String($('Make CV input').first().json.offer.company || 'Company').replace(/[^\p{L}\p{N}]+/gu, '_').replace(/^_+|_+$/g, '').slice(0, 40) || 'Company';
const kind = 'CV';
return [{ json: { ok: true, filename: kind + '_' + company + '.pdf', b64: buf.toString('base64') } }];
